static void mix_mono_at(StereoBuffer& dst, const Buffer& src,
                        double t_sec, float gain, int sr)
{
    const size_t off = (size_t)(t_sec * sr);
    for (size_t i = 0; i < src.size() && off + i < dst.size(); ++i) {
        dst.L[off + i] += src[i] * gain;
        dst.R[off + i] += src[i] * gain;
    }
}

static void mix_stereo_at(StereoBuffer& dst, const StereoBuffer& src,
                          double t_sec, float gain, int sr)
{
    const size_t off = (size_t)(t_sec * sr);
    for (size_t i = 0; i < src.size() && off + i < dst.size(); ++i) {
        dst.L[off + i] += src.L[i] * gain;
        dst.R[off + i] += src.R[i] * gain;
    }
}

static StereoBuffer make_flute(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer mono = make_buffer(d, sr);

    Oscillator o1(WaveShape::Sine,     freq,       0.52);
    Oscillator o2(WaveShape::Sine,     freq * 2.0, 0.26);
    Oscillator o3(WaveShape::Triangle, freq * 3.0, 0.10);

    NoiseGenerator ng(31u);
    double vib_phase = 0.0;
    for (size_t i = 0; i < mono.size(); ++i) {
        vib_phase += TWO_PI * 5.8 / sr;
        if (vib_phase >= TWO_PI) vib_phase -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.08) / 0.08));
        double vib = std::sin(vib_phase) * freq * (std::pow(2.0, 9.0/1200.0) - 1.0) * ve;
        o1.frequency = freq + vib;
        o2.frequency = freq * 2.0 + vib * 2.0;
        float breath = ng.tick_white() * 0.04f * (float)std::min(1.0, t / 0.05);
        mono[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + breath;
    }

    HighPassFilter hpf(350.0, sr);
    hpf.process(mono);
    BiquadEQ air(BiquadEQ::Type::HighShelf, 5500.0, 3.5, 0.7);
    air.process(mono, sr);

    double rel = std::min(0.06, d * 0.20);
    ADSR env(0.010, d * 0.08, 0.90, rel);
    env.apply(mono, d, std::max(0.0, d - rel), sr);

    return haas_widen(mono, 5.0, sr);
}

static Buffer make_trumpet(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);

    Oscillator o1(WaveShape::BL_Sawtooth, freq,         0.48);
    Oscillator o2(WaveShape::BL_Sawtooth, freq * 1.006, 0.30);
    Oscillator o3(WaveShape::Sine,        freq * 2.0,   0.14);
    Oscillator o4(WaveShape::Sine,        freq * 3.0,   0.06);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);

    BiquadEQ peak(BiquadEQ::Type::Peak,      1800.0,  5.0, 2.5);
    BiquadEQ hcut(BiquadEQ::Type::HighShelf, 8000.0, -4.0, 0.7);
    peak.process(buf, sr);
    hcut.process(buf, sr);
    distortion::apply_soft_clip(buf, 1.30f);

    double atk = std::min(0.04, d * 0.12);
    double rel = std::min(0.10, d * 0.15);
    DAHDSR env(0.0, atk, 0.0, d * 0.08, 0.90, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

static Buffer make_oboe(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    FMSynth fm;
    fm.carrier_freq   = freq;
    fm.modulator_freq = freq * 3.0;
    fm.mod_index      = 1.6;
    fm.amplitude      = 0.55;
    Buffer buf = fm.render(d, sr);

    Oscillator sq(WaveShape::BL_Square, freq, 0.28);
    for (size_t i = 0; i < buf.size(); ++i) buf[i] += sq.tick(sr);

    BiquadEQ nasal(BiquadEQ::Type::Peak, 1400.0, 4.0, 2.2);
    nasal.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 5500.0, 0.72);
    lp.process(buf, sr);

    double rel = std::min(0.08, d * 0.18);
    ADSR env(0.012, d * 0.10, 0.82, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

static Buffer make_clarinet(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    FMSynth fm;
    fm.carrier_freq   = freq;
    fm.modulator_freq = freq * 3.0;
    fm.mod_index      = 1.4;
    fm.amplitude      = 0.52;
    Buffer buf = fm.render(d, sr);

    Oscillator sq(WaveShape::BL_Square, freq, 0.30);
    for (size_t i = 0; i < buf.size(); ++i) buf[i] += sq.tick(sr);

    BiquadEQ throat(BiquadEQ::Type::Peak, 1500.0, 3.5, 2.0);
    SVFilter lp(SVFilter::Mode::LowPass, 5500.0, 0.75);
    throat.process(buf, sr);
    lp.process(buf, sr);

    double rel = std::min(0.10, d * 0.20);
    ADSR env(0.015, d * 0.12, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

static Buffer make_french_horn(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);

    Oscillator sq(WaveShape::BL_Square, freq,       0.42);
    Oscillator si(WaveShape::Sine,      freq,       0.32);
    Oscillator h2(WaveShape::Sine,      freq * 2.0, 0.18);
    Oscillator h3(WaveShape::Sine,      freq * 3.0, 0.08);
    for (auto& s : buf) s = sq.tick(sr) + si.tick(sr) + h2.tick(sr) + h3.tick(sr);

    BiquadEQ bell(BiquadEQ::Type::Peak,    1200.0, 2.5, 2.0);
    SVFilter   lp(SVFilter::Mode::LowPass, 3500.0, 0.75);
    bell.process(buf, sr);
    lp.process(buf, sr);

    double atk = std::min(0.06, d * 0.15);
    double rel = std::min(0.15, d * 0.18);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.85, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

static StereoBuffer make_strings(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer mono = make_buffer(d, sr);

    Oscillator o1(WaveShape::BL_Sawtooth, freq,         0.48);
    Oscillator o2(WaveShape::BL_Sawtooth, freq * 1.005, 0.32);
    Oscillator o3(WaveShape::BL_Sawtooth, freq * 2.0,   0.14);

    double vib_phase = 0.0;
    const double vib_depth = freq * (std::pow(2.0, 8.0/1200.0) - 1.0);
    for (size_t i = 0; i < mono.size(); ++i) {
        vib_phase += TWO_PI * 5.5 / sr;
        if (vib_phase >= TWO_PI) vib_phase -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.10) / 0.10));
        double vib = std::sin(vib_phase) * vib_depth * ve;
        o1.frequency = freq + vib;
        o2.frequency = freq * 1.005 + vib;
        mono[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    }

    BiquadEQ form(BiquadEQ::Type::Peak, 2500.0, 3.5, 2.5);
    form.process(mono, sr);
    HighPassFilter hpf(160.0, sr);
    hpf.process(mono);

    double atk = std::min(0.07, d * 0.15);
    double rel = std::min(0.28, d * 0.22);
    DAHDSR env(0.0, atk, 0.0, d * 0.08, 0.82, rel);
    env.apply(mono, d, std::max(0.0, d - rel), sr);

    return haas_widen(mono, 12.0, sr);
}

static Buffer make_viola(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer buf = make_buffer(d, sr);

    Oscillator o1(WaveShape::BL_Sawtooth, freq,        0.52);
    Oscillator o2(WaveShape::BL_Sawtooth, freq * 2.0,  0.24);
    Oscillator o3(WaveShape::Triangle,    freq * 3.0,  0.12);

    double fl = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        fl += TWO_PI * 5.8 / sr;
        if (fl >= TWO_PI) fl -= TWO_PI;
        buf[i] = (o1.tick(sr) + o2.tick(sr) + o3.tick(sr)) * (1.0f + 0.03f * (float)std::sin(fl));
    }

    BiquadEQ nasal(BiquadEQ::Type::Peak,    600.0, 3.0, 2.0);
    SVFilter   lp(SVFilter::Mode::LowPass, 5000.0, 0.72);
    nasal.process(buf, sr);
    lp.process(buf, sr);

    double atk = std::min(0.08, d * 0.18);
    double rel = std::min(0.22, d * 0.22);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

static Buffer make_cello(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer buf = make_buffer(d, sr);

    Oscillator o1(WaveShape::BL_Sawtooth, freq,       0.50);
    Oscillator o2(WaveShape::BL_Sawtooth, freq * 2.0, 0.22);
    Oscillator o3(WaveShape::Sine,        freq * 0.5, 0.26);

    double fl = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        fl += TWO_PI * 6.0 / sr;
        if (fl >= TWO_PI) fl -= TWO_PI;
        buf[i] = (o1.tick(sr) + o2.tick(sr) + o3.tick(sr)) * (1.0f + 0.04f * (float)std::sin(fl));
    }

    BiquadEQ body(BiquadEQ::Type::Peak,    320.0, 3.5, 1.8);
    SVFilter   lp(SVFilter::Mode::LowPass, 4500.0, 0.70);
    body.process(buf, sr);
    lp.process(buf, sr);

    double atk = std::min(0.10, d * 0.18);
    double rel = std::min(0.38, d * 0.25);
    DAHDSR env(0.0, atk, 0.0, d * 0.12, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

static StereoBuffer make_pizzicato(double freq, double dur, int sr)
{
    double d = std::max(0.08, std::min(dur, 0.40));
    Buffer mono = make_buffer(d, sr);

    Oscillator o1(WaveShape::Triangle, freq,       0.62);
    Oscillator o2(WaveShape::Sine,     freq * 2.0, 0.26);
    Oscillator o3(WaveShape::Sine,     freq * 3.0, 0.08);
    for (auto& s : mono) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);

    BiquadEQ body(BiquadEQ::Type::Peak, 800.0, 2.0, 1.5);
    body.process(mono, sr);

    for (size_t i = 0; i < mono.size(); ++i) {
        double t = (double)i / sr;
        mono[i] *= (float)((t < 0.003) ? t / 0.003 : std::exp(-(t - 0.003) * 16.0));
    }
    return haas_widen(mono, 7.0, sr);
}

static Buffer make_contrabass(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer buf = make_buffer(d, sr);

    Oscillator o1(WaveShape::Sine,        freq,        0.58);
    Oscillator o2(WaveShape::Sine,        freq * 2.0,  0.28);
    Oscillator o3(WaveShape::BL_Sawtooth, freq,        0.16);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);

    SVFilter lp(SVFilter::Mode::LowPass, 700.0, 0.65);
    lp.process(buf, sr);

    double atk = std::min(0.12, d * 0.20);
    double rel = std::min(0.50, d * 0.28);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.88, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

static StereoBuffer make_horn_pad(double freq, double dur, int sr)
{
    double d = std::max(0.05, dur);
    Supersaw saw;
    saw.frequency    = freq;
    saw.voices       = 5;
    saw.detune_cents = 12.0;
    saw.amplitude    = 0.48;
    saw.mix_center   = 0.62;
    Buffer mono = saw.render(d, sr);

    BiquadEQ mid(BiquadEQ::Type::Peak,     1400.0, 2.5, 2.0);
    SVFilter  lp(SVFilter::Mode::LowPass,  4000.0, 0.72);
    mid.process(mono, sr);
    lp.process(mono, sr);

    double atk = std::min(0.30, d * 0.20);
    double rel = std::min(0.50, d * 0.28);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.82, rel);
    env.apply(mono, d, std::max(0.0, d - rel), sr);

    StereoBuffer sb = haas_widen(mono, 14.0, sr);
    Reverb rvL; rvL.room_size = 0.78f; rvL.wet = 0.28f; rvL.dry = 0.86f; rvL.init(sr);
    Reverb rvR; rvR.room_size = 0.80f; rvR.wet = 0.28f; rvR.dry = 0.86f; rvR.init(sr);
    rvL.process(sb.L);
    rvR.process(sb.R);
    return sb;
}

static Buffer make_timpani(double pitch_freq = 90.0)
{
    const double dur = 1.20;
    Buffer buf = make_buffer(dur, SR);
    NoiseGenerator ng(41u);
    double phase = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        double t = (double)i / SR;
        double f = pitch_freq * (1.0 + 0.12 * std::exp(-t * 12.0));
        phase += TWO_PI * f / SR;
        if (phase >= TWO_PI) phase -= TWO_PI;
        buf[i] = (float)(std::sin(phase) * std::exp(-t * 4.5))
               + ng.tick_white() * (float)std::exp(-t * 30.0) * 0.18f;
    }
    SVFilter lp(SVFilter::Mode::LowPass, 420.0, 0.8);
    lp.process(buf, SR);
    normalize(buf, 0.90f);
    return buf;
}

static Buffer make_orch_snare()
{
    const double dur = 0.22;
    NoiseGenerator ng(17u);
    Buffer buf = ng.render(dur, SR);
    SVFilter bp(SVFilter::Mode::BandPass, 2200.0, 2.2);
    bp.process(buf, SR);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 28.0);
    Buffer body = make_buffer(dur, SR);
    Oscillator ob(WaveShape::Sine, 220.0, 0.45);
    for (size_t i = 0; i < body.size(); ++i)
        body[i] = ob.tick(SR) * (float)std::exp(-(double)i / SR * 40.0);
    mix_into(buf, body, 0.55f);
    normalize(buf, 0.75f);
    return buf;
}

static Buffer make_crash()
{
    const double dur = 1.80;
    NoiseGenerator ng(199u);
    Buffer buf = ng.render(dur, SR);
    HighPassFilter hpf(5000.0, SR);
    hpf.process(buf);
    BiquadEQ shim(BiquadEQ::Type::Peak, 8000.0, 3.0, 3.0);
    shim.process(buf, SR);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 2.8);
    normalize(buf, 0.42f);
    return buf;
}

static Buffer make_closed_hat()
{
    const double dur = 0.045;
    NoiseGenerator ng(7u);
    Buffer buf = ng.render(dur, SR);
    HighPassFilter hpf(9500.0, SR);
    hpf.process(buf);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 70.0);
    normalize(buf, 0.28f);
    return buf;
}

static Buffer make_open_hat()
{
    const double dur = 0.20;
    NoiseGenerator ng(77u);
    Buffer buf = ng.render(dur, SR);
    HighPassFilter hpf(8000.0, SR);
    hpf.process(buf);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 10.0);
    normalize(buf, 0.35f);
    return buf;
}

static void print_help(const char* prog) {
    std::cout
        << "Love-Colored Master Spark - Orchestral Arrangement\n"
        << "Usage:\n  " << prog << " [options]\n\n"
        << "  -o, --output <file>   Output WAV (default: spark.wav)\n"
        << "      --play            Play after rendering\n"
        << "  -h, --help            Show help\n";
}

int main(int argc, char** argv)
{
    std::string output  = "spark.wav";
    bool        do_play = false;

    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "-o" || a == "--output") {
            if (i + 1 < argc) output = argv[++i];
            else { std::cerr << "Missing argument\n"; return 1; }
        } else if (a == "--play") {
            do_play = true;
        } else if (a == "-h" || a == "--help") {
            print_help(argv[0]); return 0;
        } else {
            std::cerr << "Unknown: " << a << "\n"; return 1;
        }
    }

    global_config().sample_rate = SR;
    global_config().channels    = 2;
    global_config().bits        = 16;

    constexpr double TOTAL_DUR = 235.0;
    const size_t total = (size_t)(TOTAL_DUR * SR);

    std::cout << "Love-Colored Master Spark - Orchestral Arrangement\n"
              << "  169 BPM  |  " << std::fixed << std::setprecision(1)
              << TOTAL_DUR << " s\n\n";

    StereoBuffer master(total, 0.0f);

    const Buffer kick_buf  = make_timpani(73.4);
    const Buffer snare_buf = make_orch_snare();
    const Buffer hat_c_buf = make_closed_hat();
    const Buffer hat_o_buf = make_open_hat();
    const Buffer crash_buf = make_crash();

    std::cout << "  [1/12] Timpani / percussion...\n" << std::flush;
    for (int i = 0; i < kick_times_count;  ++i) mix_mono_at(master, kick_buf,  kick_times[i],  0.80f, SR);
    for (int i = 0; i < snare_times_count; ++i) mix_mono_at(master, snare_buf, snare_times[i], 0.55f, SR);
    for (int i = 0; i < hat_c_times_count; ++i) mix_mono_at(master, hat_c_buf, hat_c_times[i], 0.18f, SR);
    for (int i = 0; i < hat_o_times_count; ++i) mix_mono_at(master, hat_o_buf, hat_o_times[i], 0.25f, SR);
    for (int i = 0; i < crash_times_count; ++i) mix_mono_at(master, crash_buf, crash_times[i], 0.48f, SR);

    std::cout << "  [2/12] Contrabass (" << bass_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < bass_notes_count; ++i) {
        const NoteEvent& n = bass_notes[i];
        mix_mono_at(master, make_contrabass(n.freq, n.dur, SR), n.t, 0.75f, SR);
    }

    std::cout << "  [3/12] Cello (" << cello_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < cello_notes_count; ++i) {
        const NoteEvent& n = cello_notes[i];
        mix_mono_at(master, make_cello(n.freq, n.dur, SR), n.t, 0.70f, SR);
    }

    std::cout << "  [4/12] Viola (" << viola_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < viola_notes_count; ++i) {
        const NoteEvent& n = viola_notes[i];
        mix_mono_at(master, make_viola(n.freq, n.dur, SR), n.t, 0.65f, SR);
    }

    std::cout << "  [5/12] Pizzicato strings (" << pizz_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < pizz_notes_count; ++i) {
        const NoteEvent& n = pizz_notes[i];
        StereoBuffer sb = make_pizzicato(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.60f, SR);
    }

    std::cout << "  [6/12] French horn (" << horn_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < horn_notes_count; ++i) {
        const NoteEvent& n = horn_notes[i];
        mix_mono_at(master, make_french_horn(n.freq, n.dur, SR), n.t, 0.62f, SR);
    }

    std::cout << "  [7/12] Clarinet (" << clarinet_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < clarinet_notes_count; ++i) {
        const NoteEvent& n = clarinet_notes[i];
        mix_mono_at(master, make_clarinet(n.freq, n.dur, SR), n.t, 0.60f, SR);
    }

    std::cout << "  [8/12] Horn pad (" << pad_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < pad_notes_count; ++i) {
        const NoteEvent& n = pad_notes[i];
        StereoBuffer sb = make_horn_pad(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.52f, SR);
    }

    std::cout << "  [9/12] String ensemble (" << strings_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < strings_notes_count; ++i) {
        const NoteEvent& n = strings_notes[i];
        if (n.dur < 0.005f) continue;
        StereoBuffer sb = make_strings(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.62f, SR);
    }

    std::cout << "  [10/12] Oboe (" << oboe_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < oboe_notes_count; ++i) {
        const NoteEvent& n = oboe_notes[i];
        mix_mono_at(master, make_oboe(n.freq, n.dur, SR), n.t, 0.65f, SR);
    }

    std::cout << "  [11/12] Trumpet lead (" << trumpet_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < trumpet_notes_count; ++i) {
        const NoteEvent& n = trumpet_notes[i];
        mix_mono_at(master, make_trumpet(n.freq, n.dur, SR), n.t, 0.72f, SR);
    }

    std::cout << "  [12/12] Flute (" << flute_notes_count << " notes)...\n" << std::flush;
    for (int i = 0; i < flute_notes_count; ++i) {
        const NoteEvent& n = flute_notes[i];
        StereoBuffer sb = make_flute(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.65f, SR);
    }

    std::cout << "\n  Master bus...\n" << std::flush;

    Reverb rvL; rvL.room_size = 0.88f; rvL.wet = 0.18f; rvL.dry = 0.94f; rvL.init(SR);
    Reverb rvR; rvR.room_size = 0.90f; rvR.wet = 0.18f; rvR.dry = 0.94f; rvR.init(SR);
    rvL.process(master.L);
    rvR.process(master.R);

    ParametricEQ eq;
    eq.low_shelf  = BiquadEQ(BiquadEQ::Type::LowShelf,  120.0, -2.0, 0.7);
    eq.peak       = BiquadEQ(BiquadEQ::Type::Peak,      3500.0,  1.5, 1.5);
    eq.high_shelf = BiquadEQ(BiquadEQ::Type::HighShelf, 9000.0,  2.0, 0.7);
    eq.process(master, SR);

    distortion::apply_soft_clip(master.L, 1.10f);
    distortion::apply_soft_clip(master.R, 1.10f);

    fade_in(master,  0.25, SR);
    fade_out(master, 3.00, SR);

    normalize(master, 0.92f);
    clamp_buffer(master);

    std::cout << "  Writing: " << output << "\n";
    save_wav_stereo(master, output, SR);
    std::cout << "  Done.\n";

    if (do_play) {
        std::cout << "  Playing (press Enter to stop)...\n";
        PlaybackHandle h = play_async(master, SR);
        std::thread([h]() mutable { std::cin.get(); h.stop(); }).detach();
        h.wait();
        std::cout << "  Playback finished.\n";
    }

    return 0;
}
